let is_continuation_byte c = Char.code c land 0b1100_0000 = 0b1000_0000

(* Skip leading continuation bytes in [s.[start .. end_)]: the tail of a
   multi-byte sequence whose lead byte falls before [start]. *)
let skip_leading_continuations s ~start ~end_ =
  let i = ref start in
  while !i < end_ && is_continuation_byte s.[!i] do
    incr i
  done;
  !i

let safe_range s ~start ~end_ =
  let start' = skip_leading_continuations s ~start ~end_ in
  let end' =
    let i = ref start' in
    let last_ok = ref start' in
    (try
       while !i < end_ do
         let d = String.get_utf_8_uchar s !i in
         let len = Uchar.utf_decode_length d in
         (* [len] bytes starting at [i] exist in [s] (that's how
            [get_utf_8_uchar] computed it), but they may run past
            [end_], which is what we actually care about here --
            regardless of whether the sequence is itself well-formed. *)
         if !i + len > end_ then raise Exit
         else begin
           i := !i + len;
           last_ok := !i
         end
       done
     with
    | Exit -> ());
    !last_ok
  in
  (start', end')

(* Decode and count the number of code points that were successfully decoded
   and the number of invalid bytes. *)
let cp_count s =
  let end_ = String.length s in
  let i = ref 0 in
  let cp_count = ref 0 in
  (try
     while !i < end_ do
       let d = String.get_utf_8_uchar s !i in
       let len = Uchar.utf_decode_length d in
       assert (len >= 1);
       if !i + len > end_ then raise Exit
       else begin
         i := !i + len;
         incr cp_count
       end
     done
   with
  | Exit -> ());
  !cp_count

let is_whitespace = function
  | ' '
  | '\t'
  | '\n'
  | '\r' ->
      true
  | _ -> false

type normalized = { text : string; norm_to_raw : int array }

let normalize_whitespace (raw : string) : normalized =
  let n = String.length raw in
  let buf = Buffer.create n in
  let positions = ref [] in
  let i = ref 0 in
  while !i < n do
    if is_whitespace raw.[!i] then begin
      positions := !i :: !positions;
      Buffer.add_char buf ' ';
      while !i < n && is_whitespace raw.[!i] do
        incr i
      done
    end
    else begin
      positions := !i :: !positions;
      Buffer.add_char buf raw.[!i];
      incr i
    end
  done;
  positions := n :: !positions;
  (* Positions were accumulated newest-first, one per normalized byte plus
     the trailing sentinel; reverse once to put them back in order. *)
  {
    text = Buffer.contents buf;
    norm_to_raw = Array.of_list (List.rev !positions);
  }

let raw_range_of_normalized (n : normalized) ~start ~end_ =
  (n.norm_to_raw.(start), n.norm_to_raw.(end_))

let sanitize_utf8 s =
  let n = String.length s in
  let start = skip_leading_continuations s ~start:0 ~end_:n in
  let buf = Buffer.create (n - start) in
  (try
     let i = ref start in
     while !i < n do
       let d = String.get_utf_8_uchar s !i in
       let len = Uchar.utf_decode_length d in
       if Uchar.utf_decode_is_valid d then begin
         Buffer.add_substring buf s !i len;
         i := !i + len
       end
       else if !i + len >= n then
         (* This malformed unit runs up to the very end of [s]: a sequence
            truncated by slicing rather than necessarily corrupt data.
            Drop it and stop. *)
         raise Exit
       else begin
         Buffer.add_utf_8_uchar buf Uchar.rep;
         i := !i + len
       end
     done
   with
  | Exit -> ());
  Buffer.contents buf
